#if DEBUG
import Foundation

/// Deterministic presentation fixture; never sent to a model or a server.
enum ActivityPreview {
    @MainActor static func prepare(_ store: WorkspaceStore) {
        let args = ProcessInfo.processInfo.arguments
        guard args.contains("--ui-testing"), args.contains("--activity-preview"), args.contains("--reset") else { return }
        do {
            let artifacts = try JSONDecoder().decode([SandboxArtifact].self, from: Data(artifactJSON.utf8))
            let files = try store.importExecutionArtifacts(artifacts)
            var reply = ChatMessage(role: "assistant", text: "共 6 页：推理瓶颈、KV 缓存、连续批处理和投机解码，最后一页是选型建议。")
            reply.reasoning = ReasoningTrace(text: "先整理推理优化的三个主题，再生成演示文稿并检查输出。", state: .complete, elapsed: 7)
            reply.codeRuns = [
                CodeExecutionRun(id: "draft", title: "生成演示文稿", state: "failed", code: "build_presentation()", result: SandboxExecution(status: "failed", stdout: "", stderr: "ValueError: unsupported shape type", error: "首次生成失败，已保留执行记录。", text: "", artifacts: [])),
                CodeExecutionRun(id: "deck", title: "修正形状参数并生成 PPTX", attachmentIDs: [files[0].id], state: "complete", code: "presentation.save('llm-inference-overview.pptx')", result: SandboxExecution(status: "complete", stdout: "已保存演示文稿", stderr: "", text: "", artifacts: [SandboxArtifact(name: files[0].name, mime: files[0].type, base64: "")])),
                CodeExecutionRun(id: "preview", title: "检查幻灯片预览", attachmentIDs: [files[1].id], state: "complete", code: "render_slide('llm-inference-overview.pptx', page=1)", result: SandboxExecution(status: "complete", stdout: "已渲染第 1 页", stderr: "", text: "", artifacts: [SandboxArtifact(name: files[1].name, mime: files[1].type, base64: "")]))
            ]
            reply.activityOrder = ["reasoning", "code:draft", "code:deck", "code:preview"]
            reply.attachments = files
            store.newChat(); store.update { chat in
                chat.draft = nil; chat.input = ""; chat.title = "演示文稿流程示例"
                chat.messages = [ChatMessage(role: "user", text: "制作一份 LLM 推理优化的演示文稿，并预览检查。"), reply]
            }; store.persist()
        } catch { store.error = error.localizedDescription }
    }
    private static let artifactJSON = #"""
[{"name": "llm-inference-overview.pptx", "mime": "application/vnd.openxmlformats-officedocument.presentationml.presentation", "base64": ""}, {"name": "slide-preview.png", "mime": "image/png", "base64": ""}]
"""#
}
#endif
